// Single source of truth for the tool catalog.
// The atlas-write skill appends one entry here per documented tool; the sidebar
// (config.ts) and the homepage catalog (ToolCatalog.vue) both read from it.
//
// Product premise: the CNCF landscape is a wall of logos with no context. This catalog
// is the readable map: every entry links to a real deep-dive, grouped and labelled.

export type Maturity = 'Graduated' | 'Incubating' | 'Sandbox' | 'Archived' | 'Independent'

/**
 * How much of the site a project gets.
 *
 * 'deep' (the default) is the full six-section bilingual deep-dive under docs/.
 * It costs a recon pass over the upstream repo, so it is reserved for projects
 * enough people run to justify one: everything Graduated and Incubating.
 *
 * 'card' is a catalog entry and nothing else: name, tagline, category, maturity,
 * and a link straight to the upstream repo. It exists so the long tail of Sandbox
 * projects is still findable and still says what it is, without pretending there
 * is a deep-dive behind it. A card carries no pages, no sidebar entry, and no
 * internal link. Promoting one to 'deep' means running atlas-recon, then
 * atlas-write, then dropping the tier and repo fields.
 */
export type Tier = 'deep' | 'card'

export interface ToolEntry {
  /** URL slug. For tier 'deep' it must match docs/tools/<slug> and docs/ja/tools/<slug>. */
  slug: string
  /** Display name, e.g. "Argo CD". */
  name: string
  /** One-line English tagline shown on the catalog card. */
  tagline: string
  /** One-line Japanese tagline shown on the catalog card. */
  taglineJa: string
  /** Category. Must be one of CATEGORY_ORDER below. */
  category: string
  /** CNCF maturity (or "Independent" for non-CNCF projects). */
  maturity: Maturity
  /** Defaults to 'deep'. See Tier above. */
  tier?: Tier
  /** Upstream repository URL. Required for tier 'card', which links there instead. */
  repo?: string
}

